      ['القناة الناقلة للحيامن التي تتصل مقدمتها بالخصية ومؤخرتها بالحويصلة المنوية التي تمثل منطقة متوسعة من القناة الناقلة.', 'قناتا بيض جانبيتان؛ يتصل الجزء الخلفي لكل مبيض بقناة بيض جانبية، واللتان تتحدان لتكوّنا قناة بيض رئيسية.'],
      ['القناة القاذفة التي تتكون من اتحاد القناتين الناقلتين للحيامن، وتمتد إلى القضيب.', 'المهبل: الجزء الخلفي من الجهاز التناسلي وتفتح فيه قناة البيض الرئيسية.'],
      ['القضيب الذي يفتح في نهايته بالفتحة التناسلية التي تنطلق منها النطف أو الحيامن.', 'المستودع المنوي: تركيب كيسي يلحق بالجهاز الأنثوي (ولبعض الحشرات مستودعان أو ثلاثة)، تتصل به غدة المستودع المنوي التي تفرز سائلاً يحفظ النطف، ويرتبط بالجدار الظهري للمهبل ويستلم النطف خلال الجماع ويطلقها عند تخصيب البيوض.'],
      ['الغدتان المساعدتان: تقعان عند بداية القناة القاذفة، وتفرزان سائلاً مخاطياً يحيط بالنطف ويشكل تركيباً كيسياً حولها يدعى كيس النطف.', 'الغدد المساعدة: زوج واحد تتصل في نهايتها لتفتح في المهبل، وتتباين وظيفتها: تكوين كيس البيض في أنثى الصرصر، وللدفاع في عاملات النحل، وتعليم مسار الحشرات في النمل.']
